pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee) public {
        vm.assume(callee != address(0) && callee != address(c));
        // Deploy a helper that, when delegatecalled, writes to storage slot 0 (owner)
        Attacker attacker = new Attacker();
        bytes memory data = abi.encodeWithSignature("overwrite()");
        vm.prank(address(this));
        c.forward(address(attacker), data);
        // The reference preserves owner (constructor sets it to address(this)), buggy delegatecall allows attacker to overwrite.
        assertTrue(c.owner() == address(this));
    }
}

contract Attacker {
    uint256 slot0;
    function overwrite() external {
        assembly {
            sstore(0, 0xdead)
        }
    }
}

