contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(bytes memory data, uint256 amount) public {
        // Bound the amount to keep the test in an admissible range
        bound(amount, 1, 100 ether);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;

        // Deploy a helper contract that will steal Ether via delegatecall
        Thief thief = new Thief();
        c.forward(address(thief), data);

        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore);
    }
}

contract Thief {
    function steal() external {
        selfdestruct(payable(address(0)));
    }
}

